#pragma once
#include "workflow_settings.h"
namespace PairedAnimations {
using Json=Presets::Json;
inline bool SameSources(const Presets::Entry& a,const Presets::Entry& b){return a.controlled==b.controlled&&a.animation==b.animation&&a.controlledAnimation==b.controlledAnimation&&a.controlledPose==b.controlledPose;}
struct Pair {bool customName=false,legacyName=false;std::string id,name,original;Presets::Entry base;std::map<std::string,Presets::Entry> variants;};
struct Library {
 std::vector<Pair> pairs;unsigned next=1;
 Pair* Find(const std::string& id){for(auto& p:pairs)if(p.id==id)return &p;return nullptr;}
 const Pair* Find(const std::string& id)const{for(auto& p:pairs)if(p.id==id)return &p;return nullptr;}
 Pair* Match(const Presets::Entry& entry){if(auto p=Find(entry.pairId);p&&SameSources(p->base,entry))return p;for(auto& p:pairs)if(SameSources(p.base,entry))return &p;return nullptr;}
 bool Has(const std::string& id,const std::string& target)const{auto p=Find(id);return p&&p->variants.contains(target);}
 std::string Create(Presets::Entry entry,const std::string& name){Pair p;do{p.id="pair_"+std::to_string(next++);}while(Find(p.id));size_t limit=std::min<size_t>(150,name.size());if(limit<name.size())while(limit&&(static_cast<unsigned char>(name[limit])&0xc0)==0x80)--limit;p.name=name.substr(0,limit);p.original=entry.target;entry.enabled=true;entry.pairId=p.id;p.base=entry;p.variants[entry.target]=entry;pairs.push_back(p);return p.id;}
 bool Rename(const std::string& id,std::string name){auto p=Find(id);auto first=name.find_first_not_of(" \t\r\n");if(!p||first==name.npos)return false;name=name.substr(first,name.find_last_not_of(" \t\r\n")-first+1);if(name.size()>256)return false;p->name=name;p->customName=true;p->legacyName=false;return true;}
 bool Add(const std::string& id,Presets::Entry entry){auto p=Find(id);if(!p||!SameSources(p->base,entry)||p->variants.contains(entry.target))return false;entry.enabled=true;entry.pairId=id;p->variants[entry.target]=entry;return true;}
 bool Update(const std::string& id,Presets::Entry entry){auto p=Find(id);if(!p||!SameSources(p->base,entry)||!p->variants.contains(entry.target))return false;entry.enabled=true;entry.pairId=id;p->variants[entry.target]=entry;if(entry.target==p->original)p->base=entry;return true;}
 bool Resolve(const std::string& id,const std::string& selected,bool reuse,Presets::Entry& result)const{auto p=Find(id);if(!p)return false;auto it=p->variants.find(selected);result=it!=p->variants.end()?it->second:p->base;if(it==p->variants.end()&&reuse&&!selected.empty())result.target=selected;return true;}
 Json Encode()const{auto items=Json::array();for(auto& p:pairs){auto variants=Json::object();for(auto& [role,entry]:p.variants)variants[role]=Workflow::EntryJson(entry);items.push_back({{"id",p.id},{"name",p.name},{"custom_name",p.customName},{"original",p.original},{"base",Workflow::EntryJson(p.base)},{"variants",variants}});}return {{"schema",1},{"items",items}};}
 bool Read(const Json& json){try{if(json.at("schema")!=1||!json.at("items").is_array()||json.at("items").size()>1024)return false;Library candidate;for(auto& item:json.at("items")){Pair p;p.id=item.at("id");p.name=item.at("name");p.customName=item.value("custom_name",false);p.legacyName=!item.contains("custom_name");p.original=item.at("original");if(p.id.empty()||p.id.size()>80||p.id.find_first_not_of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")!=std::string::npos||candidate.Find(p.id)||p.name.size()>256||!Workflow::ReadEntry(item.at("base"),p.base)||p.base.target!=p.original)return false;p.base.pairId=p.id;if(!item.at("variants").is_object()||item.at("variants").size()>128)return false;for(auto& [role,data]:item.at("variants").items()){Presets::Entry entry;if(!Workflow::ReadEntry(data,entry)||role!=entry.target||!SameSources(entry,p.base))return false;entry.pairId=p.id;p.variants[role]=entry;}if(!p.variants.contains(p.original)||Workflow::EntryJson(p.variants.at(p.original))!=Workflow::EntryJson(p.base))return false;candidate.pairs.push_back(p);}*this=std::move(candidate);return true;}catch(...){return false;}}
 bool Migrate(Presets::Bank& bank){bool changed=false;for(auto& entry:bank.slots){if(auto existing=Find(entry.pairId);existing&&SameSources(existing->base,entry))continue;if(!entry.enabled)continue;Pair* p=Match(entry);if(p&&p->variants.contains(entry.target)){auto a=Workflow::EntryJson(p->variants.at(entry.target)),b=Workflow::EntryJson(entry);for(auto key:{"name","pair_id"}){a.erase(key);b.erase(key);}if(a!=b)p=nullptr;}if(!p){auto id=Create(entry,entry.name.empty()?entry.animation:entry.name);p=Find(id);p->legacyName=true;}else if(!p->variants.contains(entry.target))Add(p->id,entry);entry.pairId=p->id;changed=true;}return changed;}
};
}
